import * as THREE from './three.module.js';
export function equipRifle({scene,player,camera,canvas,targets,collisionMeshes,isActive,audio,onShot=()=>{},onHit=()=>{},isIndoor=()=>false}){
 const rifle=new THREE.Group();rifle.position.set(-.9,1.58,.32);player.add(rifle);const metal=new THREE.MeshStandardMaterial({color:'#202728',metalness:.75,roughness:.4}),grip=new THREE.MeshStandardMaterial({color:'#786a51',roughness:.85});
 function piece(w,h,d,x,y,z,material=metal){const m=new THREE.Mesh(new THREE.BoxGeometry(w,h,d),material);m.position.set(x,y,z);m.castShadow=true;rifle.add(m);return m}
 piece(.23,.27,.72,0,0,.35);piece(.27,.22,.45,0,-.025,-.22,grip);piece(.2,.2,.72,0,0,.97,grip);piece(.13,.13,.7,0,.025,1.58);piece(.16,.05,.8,0,.17,.5);piece(.12,.33,.19,0,-.25,.28,grip);const mag=piece(.16,.42,.23,0,-.32,.61);mag.rotation.x=-.16;piece(.08,.11,.14,0,.23,1.24);piece(.15,.12,.2,0,.23,.2);
 const muzzle=new THREE.Object3D();muzzle.position.set(0,.03,1.98);rifle.add(muzzle);const flash=new THREE.Mesh(new THREE.ConeGeometry(.17,.6,8),new THREE.MeshBasicMaterial({color:'#ffe99a',transparent:true,opacity:.9}));flash.rotation.x=Math.PI/2;flash.position.set(0,.03,2.15);flash.visible=false;rifle.add(flash);
 const cross=document.querySelector('#cross'),ammoEl=document.querySelector('#ammo'),hitEl=document.querySelector('#hits'),statusEl=document.querySelector('#weapon-status');let ammo=30,hits=0,shots=0,aiming=false,aimHeld=false,aimToggle=false,held=false,queued=false,lastShot=-1000,reloadEnd=0,flashEnd=0,recoil=0,hitEnd=0,simTime=0,baseMount={x:-.78,y:1.58,z:.32},moveSpeed=0,crouch=0,reduced=false;const effects=[];const ray=new THREE.Raycaster();
 function reload(){if(!isActive()||reloadEnd||ammo===30)return;reloadEnd=simTime+1500;audio?.reload();statusEl.textContent='RELOADING';held=false;queued=false}
 function fire(now){if(now-lastShot<125||reloadEnd)return;if(ammo===0){reload();return}lastShot=now;ammo--;shots++;recoil=.12;flashEnd=now+55;audio?.shot(isIndoor());onShot();scene.updateMatrixWorld(true);ray.setFromCamera(new THREE.Vector2(0,0),camera);ray.far=180;const objects=[...collisionMeshes,...targets.map(t=>t.board)];const cameraHits=ray.intersectObjects(objects,false);const destination=cameraHits.length?cameraHits[0].point:ray.ray.at(180,new THREE.Vector3());const origin=muzzle.getWorldPosition(new THREE.Vector3());ray.set(origin,new THREE.Vector3().subVectors(destination,origin).normalize());ray.far=origin.distanceTo(destination)+.15;const muzzleHits=ray.intersectObjects(objects,false);const hit=muzzleHits[0],end=hit?hit.point:destination;cross.classList.toggle('blocked',!!hit&&hit.distance<1.3);
  const tracer=new THREE.Line(new THREE.BufferGeometry().setFromPoints([origin,end]),new THREE.LineBasicMaterial({color:'#ffe49d',transparent:true,opacity:.85}));scene.add(tracer);effects.push({mesh:tracer,end:now+65});
  if(hit){const target=targets.find(t=>t.board===hit.object);if(target){target.hits++;hits++;target.flashUntil=now+180;hitEnd=now+180;const local=target.board.worldToLocal(hit.point.clone());const quality=Math.hypot(local.x,local.y)<.35?100:50;onHit(target.board.userData.target,quality);audio?.hit();const feedback=document.querySelector('#hit-feedback');feedback.textContent=quality===100?'+100  BULLSEYE':'+50  TARGET HIT';feedback.style.opacity='1'}
   const normal=hit.face.normal.clone().transformDirection(hit.object.matrixWorld);const mark=new THREE.Mesh(new THREE.CircleGeometry(.055,8),new THREE.MeshBasicMaterial({color:target?'#3e2417':'#28251d',side:THREE.DoubleSide}));mark.position.copy(hit.point).addScaledVector(normal,.014);mark.quaternion.setFromUnitVectors(new THREE.Vector3(0,0,1),normal);scene.add(mark);effects.push({mesh:mark,end:now+12000});
   const spark=new THREE.Mesh(new THREE.SphereGeometry(.1,6,4),new THREE.MeshBasicMaterial({color:'#ffd89a'}));spark.position.copy(hit.point);scene.add(spark);effects.push({mesh:spark,end:now+65});
  }ammoEl.textContent=String(ammo).padStart(2,'0');document.querySelector('#ammo-progress').style.width=`${ammo/30*100}%`;document.querySelector('#weapon-hud').classList.toggle('low',ammo<=5);hitEl.textContent=`${hits} TARGET HITS`;
 }
 canvas.addEventListener('contextmenu',e=>e.preventDefault());canvas.addEventListener('pointerdown',e=>{if(!isActive())return;if(e.button===0){held=true;queued=true}else if(e.button===2)aimHeld=true});window.addEventListener('pointerup',e=>{if(e.button===0)held=false;if(e.button===2)aimHeld=false});document.addEventListener('keydown',e=>{if(!isActive())return;if(e.code==='KeyQ'&&!e.repeat)aimToggle=!aimToggle;if(e.code==='KeyR')reload();if(e.code==='KeyJ'&&!e.repeat){queued=true}});document.addEventListener('keyup',e=>{if(e.code==='KeyJ')held=false});
 const fireButton=document.querySelector('#fire-touch');fireButton?.addEventListener('pointerdown',e=>{e.preventDefault();held=true;queued=true});fireButton?.addEventListener('pointerup',()=>held=false);
 const muzzleLight=new THREE.PointLight('#ffcc76',0,5,2);muzzleLight.position.set(0,.03,2);rifle.add(muzzleLight);
 function update(dt,active){if(active)simTime+=dt*1000;const now=simTime;if(!active){held=false;queued=false;aimHeld=false;aimToggle=false}aiming=aimHeld||aimToggle;
  if(reloadEnd&&now>=reloadEnd){ammo=30;ammoEl.textContent='30';document.querySelector('#ammo-progress').style.width='100%';document.querySelector('#weapon-hud').classList.remove('low');reloadEnd=0;statusEl.textContent='CARBINE • AUTO'}
  if(active&&(held||queued)){fire(now);queued=false}flash.visible=active&&now<flashEnd;muzzleLight.intensity=flash.visible?12:0;flash.rotation.z+=dt*13;recoil=Math.max(0,recoil-dt*.8);
  const sway=reduced?0:Math.sin(now*.008)*Math.min(moveSpeed*.0025,.025);rifle.position.set(baseMount.x+sway,baseMount.y-crouch*.36,baseMount.z-recoil);rifle.rotation.x=(reloadEnd?-.45:0)+(reduced?0:recoil*.18);rifle.rotation.z=reloadEnd?.18:0;mag.position.y=-.32-(reloadEnd?Math.sin(Math.PI*Math.max(0,1-(reloadEnd-now)/1500))*.3:0);
  cross.classList.toggle('hit',now<hitEnd);cross.classList.toggle('aiming',aiming);document.querySelector('#hit-feedback').style.opacity=now<hitEnd+250?'1':'0';if(!aiming)cross.style.width=cross.style.height=`${22+moveSpeed*.7+recoil*40}px`;else cross.style.width=cross.style.height='14px';
  for(const t of targets)t.board.material.emissive.setHex(now<t.flashUntil?0x99702f:0);
  for(let i=effects.length-1;i>=0;i--)if(now>effects[i].end){scene.remove(effects[i].mesh);effects[i].mesh.geometry.dispose();effects[i].mesh.material.dispose();effects.splice(i,1)}
 }
 return {update,isAiming:()=>aimHeld||aimToggle,isFiring:()=>held||queued,stats:()=>({ammo,hits,shots,reloading:!!reloadEnd}),kick:()=>recoil,reset(){ammo=30;reloadEnd=0;held=false;queued=false;ammoEl.textContent='30';document.querySelector('#ammo-progress').style.width='100%';document.querySelector('#weapon-hud').classList.remove('low');statusEl.textContent='CARBINE • AUTO'},mount(value){baseMount={...value}},motion(speed,crouchAmount,motionReduced){moveSpeed=speed;crouch=crouchAmount;reduced=motionReduced}};
}
